"use client";

import React, { useState, useEffect, useCallback } from "react";
import Image from "next/image";
import { X, ChevronLeft, ChevronRight, ZoomIn } from "lucide-react";
import { cn } from "@/lib/utils";

interface GalleryItem {
  id: string;
  src: string;
  alt: string;
  title: string;
  description: string;
}

const GALLERY_ITEMS: GalleryItem[] = [
  {
    id: "g1",
    src: "/images/gallery/gallery-1.jpg",
    alt: "Top Training Institute Student Celebration & Certification",
    title: "Student Graduation & Celebration",
    description: "Celebrating milestone achievements, certificates, and student success with trainers.",
  },
  {
    id: "g2",
    src: "/images/gallery/gallery-2.jpg",
    alt: "Instructors and trainees celebrating completion",
    title: "Mentorship & Guidance",
    description: "Dedicated instructors and trainees sharing memorable moments together.",
  },
  {
    id: "g3",
    src: "/images/gallery/gallery-3.jpg",
    alt: "Top Training Institute Community",
    title: "Inspiring Training Community",
    description: "Fostering teamwork, career networking, and professional growth in Addis Ababa.",
  },
  {
    id: "g4",
    src: "/images/gallery/gallery-4.jpg",
    alt: "Hands-on Classroom Session",
    title: "Interactive Classroom Training",
    description: "Focused coursework, practical exercises, and interactive learning in modern classrooms.",
  },
  {
    id: "g5",
    src: "/images/gallery/gallery-5.jpg",
    alt: "Joyful Student Community",
    title: "Collaborative Student Culture",
    description: "A welcoming, inclusive atmosphere that inspires continuous ambition and confidence.",
  },
  {
    id: "g6",
    src: "/images/gallery/gallery-6.jpg",
    alt: "Practical Skills Lab",
    title: "Practical Hands-on Learning",
    description: "Trainees actively applying skills with direct instructor support across our branches.",
  },
];

export function GallerySection() {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);

  const openLightbox = (index: number) => {
    setSelectedIndex(index);
  };

  const closeLightbox = () => {
    setSelectedIndex(null);
  };

  const showNext = useCallback(() => {
    if (selectedIndex === null) return;
    setSelectedIndex((selectedIndex + 1) % GALLERY_ITEMS.length);
  }, [selectedIndex]);

  const showPrev = useCallback(() => {
    if (selectedIndex === null) return;
    setSelectedIndex((selectedIndex - 1 + GALLERY_ITEMS.length) % GALLERY_ITEMS.length);
  }, [selectedIndex]);

  // Keyboard navigation for lightbox
  useEffect(() => {
    if (selectedIndex === null) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeLightbox();
      if (e.key === "ArrowRight") showNext();
      if (e.key === "ArrowLeft") showPrev();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [selectedIndex, showNext, showPrev]);

  return (
    <section className="py-20 lg:py-24 bg-[#edf6fb] transition-colors">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center max-w-3xl mx-auto mb-12 sm:mb-16">
          <p className="text-sky-500 font-semibold text-sm sm:text-base tracking-wide">
            Our Learning Environment
          </p>
          <h2 className="mt-2 text-3xl sm:text-4xl lg:text-5xl font-black text-slate-900 tracking-tight">
            Explore Our Gallery
          </h2>
        </div>

        {/* Gallery Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-7 lg:gap-8">
          {GALLERY_ITEMS.map((item, idx) => (
            <div
              key={item.id}
              onClick={() => openLightbox(idx)}
              className={cn(
                "group relative aspect-4/3 overflow-hidden rounded-2xl lg:rounded-3xl cursor-pointer",
                "bg-white shadow-xs hover:shadow-xl transition-all duration-300 border border-slate-200/60"
              )}
            >
              <Image
                src={item.src}
                alt={item.alt}
                fill
                sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                className="object-cover group-hover:scale-105 transition-transform duration-500"
              />

              {/* Hover Overlay */}
              <div className="absolute inset-0 bg-gradient-to-t from-slate-950/70 via-slate-950/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-5 text-white">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-base font-bold text-white drop-shadow-sm">{item.title}</h3>
                    <p className="text-xs text-slate-200 line-clamp-1 mt-0.5">{item.description}</p>
                  </div>
                  <div className="w-8 h-8 rounded-full bg-white/20 backdrop-blur-xs flex items-center justify-center text-white shrink-0 ml-2">
                    <ZoomIn className="w-4 h-4" />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Lightbox Modal */}
      {selectedIndex !== null && (
        <div
          className="fixed inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4 sm:p-6"
          onClick={closeLightbox}
        >
          {/* Close Button */}
          <button
            onClick={closeLightbox}
            className="absolute top-5 right-5 z-60 p-2.5 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer"
            aria-label="Close gallery preview"
          >
            <X className="w-6 h-6" />
          </button>

          {/* Previous Button */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              showPrev();
            }}
            className="absolute left-4 sm:left-8 z-60 p-2.5 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer"
            aria-label="Previous image"
          >
            <ChevronLeft className="w-6 h-6" />
          </button>

          {/* Next Button */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              showNext();
            }}
            className="absolute right-4 sm:right-8 z-60 p-2.5 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer"
            aria-label="Next image"
          >
            <ChevronRight className="w-6 h-6" />
          </button>

          {/* Modal Content */}
          <div
            className="relative max-w-4xl w-full max-h-[85vh] flex flex-col items-center justify-center"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="relative w-full aspect-4/3 max-h-[70vh] rounded-2xl overflow-hidden shadow-2xl border border-white/10">
              <Image
                src={GALLERY_ITEMS[selectedIndex].src}
                alt={GALLERY_ITEMS[selectedIndex].alt}
                fill
                priority
                sizes="(max-width: 1200px) 95vw, 1000px"
                className="object-contain bg-slate-950"
              />
            </div>

            {/* Caption */}
            <div className="mt-4 text-center text-white max-w-xl px-4">
              <h3 className="text-lg font-bold">
                {GALLERY_ITEMS[selectedIndex].title}
              </h3>
              <p className="mt-1 text-sm text-slate-300">
                {GALLERY_ITEMS[selectedIndex].description}
              </p>
              <p className="mt-2 text-xs text-sky-400 font-medium">
                {selectedIndex + 1} of {GALLERY_ITEMS.length}
              </p>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}
